def score(units):
    # units: list of (constraint_pass_bool, semantic_score_0_1)
    if not units:
        return 0.0
    total = sum(float(c) * s for c, s in units)
    return total / len(units)
print(score([(1,0.9),(1,0.4),(0,1.0)]))  # -> 0.4333

import numpy as np
def agreement(transferred, manual):
    # 两张同尺寸标签图
    ok = (transferred == manual)
    return ok.mean()
print(agreement(np.array([1,2,3,4]), np.array([1,2,0,4])))  # 0.75

import numpy as np
def voi(prior, likelihoods):
    # prior: (K,) 假设概率; likelihoods: (E,K,W) 每个实验在每种假设下观测的分布
    H = lambda p: -np.sum(p[p>0]*np.log(p[p>0]))
    out = []
    for lik in likelihoods:          # lik: (K,W)
        Hpost = 0.0
        for w in range(lik.shape[1]):
            joint = prior * lik[:, w]
            post = joint / joint.sum()
            Hpost += joint.sum() * H(post)
        out.append(H(prior) - Hpost)
    return np.array(out)
